+package tests
+
+import (
+	"errors"
+	"math"
+	"testing"
+	"time"
+
+	"example.com/ratelimit/ratelimit"
+)
+
+func TestBucketRejectsBadConfig(t *testing.T) {
+	c := newClock()
+	bad := []struct {
+		cap, rate float64
+		now       func() time.Time
+	}{
+		{0, 1, c.Now},
+		{-1, 1, c.Now},
+		{math.NaN(), 1, c.Now},
+		{math.Inf(1), 1, c.Now},
+		{1, 0, c.Now},
+		{1, -1, c.Now},
+		{1, math.NaN(), c.Now},
+		{1, math.Inf(1), c.Now},
+		{1, 1, nil},
+	}
+	for i, tc := range bad {
+		if _, err := ratelimit.NewBucket(tc.cap, tc.rate, tc.now); !errors.Is(err, ratelimit.ErrInvalidConfig) {
+			t.Fatalf("case %d: err = %v, want ErrInvalidConfig", i, err)
+		}
+	}
+}
+
+func TestBucketStartsFullAndRefillsFractionally(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(4, 2, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(4) {
+		t.Fatal("full bucket should allow capacity tokens")
+	}
+	if b.Allow(1) {
+		t.Fatal("empty bucket should refuse")
+	}
+	c.Advance(250 * time.Millisecond)
+	if got := b.Tokens(); got != 0.5 {
+		t.Fatalf("Tokens() = %v, want 0.5", got)
+	}
+}
+
+func TestBucketCapsAtCapacity(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(3, 10, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	c.Advance(time.Hour)
+	if got := b.Tokens(); got != 3 {
+		t.Fatalf("Tokens() = %v, want 3", got)
+	}
+}
+
+func TestBucketNoPartialConsumption(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(2, 1, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(1.5) {
+		t.Fatal("1.5 of 2 should be allowed")
+	}
+	if b.Allow(1) {
+		t.Fatal("only 0.5 left; Allow(1) should be refused")
+	}
+	if got := b.Tokens(); got != 0.5 {
+		t.Fatalf("Tokens() = %v, want 0.5 (refused Allow must take nothing)", got)
+	}
+}
+
+func TestBucketRejectsInvalidN(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(2, 1, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	c.Advance(time.Hour)
+	for _, n := range []float64{0, -1, math.NaN(), 3, math.Inf(1)} {
+		if b.Allow(n) {
+			t.Fatalf("Allow(%v) = true, want false", n)
+		}
+	}
+	if got := b.Tokens(); got != 2 {
+		t.Fatalf("Tokens() = %v, want 2 (rejected calls take nothing)", got)
+	}
+}
+
+func TestBucketClockGoingBackwards(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(10, 1, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(10) {
+		t.Fatal("full bucket should allow 10")
+	}
+	c.Advance(5 * time.Second)
+	if got := b.Tokens(); got != 5 {
+		t.Fatalf("Tokens() = %v, want 5", got)
+	}
+	c.Advance(-3 * time.Second)
+	if got := b.Tokens(); got != 5 {
+		t.Fatalf("after clock went back: Tokens() = %v, want 5", got)
+	}
+	c.Advance(4 * time.Second) // reaches 1s past the latest seen time (t+5s) -> +1 token
+	if got := b.Tokens(); got != 6 {
+		t.Fatalf("after clock passed latest time: Tokens() = %v, want 6", got)
+	}
+}

+        ("X", 0),
