+    assert_eq!(ev("1 / -0"), Err(EvalError::DivByZero));
+    assert_eq!(ev("1 % (0 * -1)"), Err(EvalError::DivByZero));
+    assert_eq!(ev("1 / 1"), Ok(1.0));
+}
+
+#[test]
+fn min_max_abs_sqrt_values() {
+    assert_eq!(ev("min(3,1,2)"), Ok(1.0));
+    assert_eq!(ev("max(3,1,2)"), Ok(3.0));
+    assert_eq!(ev("min(5)"), Ok(5.0));
+    assert_eq!(ev("abs(-2)"), Ok(2.0));
+    assert_eq!(ev("sqrt(9)"), Ok(3.0));
+    assert_eq!(ev("2^10"), Ok(1024.0));
+    assert_ne!(ev("max(3,1,2)"), Ok(1.0));
+}
+
+#[test]
+fn arity_errors_name_expected_and_got() {
+    assert_eq!(ev("abs()"), Err(EvalError::Arity { name: "abs".to_string(), expected: "1".to_string(), got: 0 }));
+    assert_eq!(ev("abs(1,2)"), Err(EvalError::Arity { name: "abs".to_string(), expected: "1".to_string(), got: 2 }));
+    assert_eq!(ev("sqrt(1,2)"), Err(EvalError::Arity { name: "sqrt".to_string(), expected: "1".to_string(), got: 2 }));
+    assert_eq!(ev("max()"), Err(EvalError::Arity { name: "max".to_string(), expected: "at least 1".to_string(), got: 0 }));
+    assert_eq!(ev("abs(4)"), Ok(4.0));
+}
+
+#[test]
+fn arity_checked_before_arguments_evaluated() {
+    assert_eq!(ev("abs(q, 1)"), Err(EvalError::Arity { name: "abs".to_string(), expected: "1".to_string(), got: 2 }));
+    assert_eq!(ev("abs(q)"), Err(EvalError::UnknownVar("q".to_string())));
+}
+
+#[test]
+fn unknown_function_separate_from_variables() {
+    assert_eq!(ev("foo(1)"), Err(EvalError::UnknownFunc("foo".to_string())));
+    assert_eq!(ev_with("x(1)", &[("x", 5.0)]), Err(EvalError::UnknownFunc("x".to_string())));
+    assert_eq!(ev("foo()"), Err(EvalError::UnknownFunc("foo".to_string())));
+    assert_eq!(ev_with("foo(q)", &[("foo", 1.0)]), Err(EvalError::UnknownFunc("foo".to_string())));
+}
+
+#[test]
+fn sqrt_domain_and_argument_order() {
+    assert_eq!(ev("sqrt(-1)"), Err(EvalError::Domain("sqrt".to_string())));
+    assert_eq!(ev("sqrt(0)"), Ok(0.0));
+    assert_eq!(ev("sqrt(-1 + q)"), Err(EvalError::UnknownVar("q".to_string())));
+    assert_eq!(ev("min(a, b)"), Err(EvalError::UnknownVar("a".to_string())));
+    assert_eq!(ev("max(1, q, 1/0)"), Err(EvalError::UnknownVar("q".to_string())));
+    assert_ne!(ev("sqrt(-1)"), Ok(0.0));
+}
+
+#[test]
+fn deep_nested_parens_do_not_overflow() {
+    let n = 100000;
+    let s = format!("{}1{}", "(".repeat(n), ")".repeat(n));
+    assert_eq!(timed(&s), Ok(1.0));
+    let bad = format!("{})", s);
