+#[test]
+fn large_sweep_is_fast() {
+    let mut s = IntervalSet::new();
+    let mut seed: u64 = 12345;
+    let mut next = || {
+        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
+        (seed >> 33) as i64
+    };
+    let mut pos: i64 = 1_000_000_000;
+    for _ in 0..300_000 {
+        let len = next() % 1001;
+        let jitter = next() % 50;
+        let lo = pos - jitter;
+        s.insert(C(lo), C(lo + len));
+        if next() % 3 == 0 {
+            s.remove(C(lo + len / 2), C(lo + len));
+        }
+        let _ = s.contains((next() % 1_000_000_001) as f64);
+        pos -= 1000;
+    }
