diff --git a/tests/loki_wall_intervals.rs b/tests/loki_wall_intervals.rs
new file mode 100644
index 0000000..6023a7a
--- /dev/null
+++ b/tests/loki_wall_intervals.rs
@@ -0,0 +1,192 @@
+use intervalkit::intervals::{Bound, IntervalSet};
+use std::time::Instant;
+
+fn c(v: i64) -> Bound {
+    Bound::Closed(v)
+}
+
+fn o(v: i64) -> Bound {
+    Bound::Open(v)
+}
+
+#[test]
+fn empty_intervals_are_ignored() {
+    let mut s = IntervalSet::new();
+    s.insert(o(2), o(2));
+    s.insert(c(2), o(2));
+    s.insert(o(2), c(2));
+    s.insert(c(3), c(2));
+    assert!(s.is_empty());
+    assert_eq!(s.ranges(), Vec::new());
+    s.insert(c(2), c(2));
+    assert!(!s.is_empty());
+    assert_eq!(s.ranges(), vec![(c(2), c(2))]);
+}
+
+#[test]
+fn open_interval_on_real_line_is_nonempty() {
+    let mut s = IntervalSet::new();
+    s.insert(o(2), o(3));
+    assert!(s.contains(2.5));
+    assert!(!s.contains(2.0));
+    assert!(!s.contains(3.0));
+    assert_eq!(s.ranges(), vec![(o(2), o(3))]);
+}
+
+#[test]
+fn touching_intervals_merge_when_union_is_one_interval() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), o(3));
+    s.insert(c(3), c(5));
+    assert_eq!(s.ranges(), vec![(c(1), c(5))]);
+
+    let mut s = IntervalSet::new();
+    s.insert(c(1), c(3));
+    s.insert(o(3), o(5));
+    assert_eq!(s.ranges(), vec![(c(1), o(5))]);
+
+    let mut s = IntervalSet::new();
+    s.insert(o(1), o(3));
+    s.insert(c(3), c(3));
+    assert_eq!(s.ranges(), vec![(o(1), c(3))]);
+}
+
+#[test]
+fn missing_shared_endpoint_keeps_intervals_separate() {
+    let mut s = IntervalSet::new();
+    s.insert(o(1), o(3));
+    s.insert(o(3), o(5));
+    assert_eq!(s.ranges(), vec![(o(1), o(3)), (o(3), o(5))]);
+
+    let mut s = IntervalSet::new();
+    s.insert(c(1), o(3));
+    s.insert(o(3), c(5));
+    assert_eq!(s.ranges(), vec![(c(1), o(3)), (o(3), c(5))]);
+}
+
+#[test]
+fn single_point_is_closed_pair() {
+    let mut s = IntervalSet::new();
+    s.insert(c(7), c(7));
+    assert_eq!(s.ranges(), vec![(c(7), c(7))]);
+    assert_eq!(s.measure(), 0);
+}
+
+#[test]
+fn remove_point_splits_interval() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), c(5));
+    s.remove(c(2), c(2));
+    assert_eq!(s.ranges(), vec![(c(1), o(2)), (o(2), c(5))]);
+}
+
+#[test]
+fn remove_open_interval_splits_interval() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), c(5));
+    s.remove(o(2), o(4));
+    assert_eq!(s.ranges(), vec![(c(1), c(2)), (c(4), c(5))]);
+}
+
+#[test]
+fn remove_empty_interval_is_ignored() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), c(5));
+    s.remove(o(2), o(2));
+    s.remove(c(4), c(3));
+    assert_eq!(s.ranges(), vec![(c(1), c(5))]);
+}
+
+#[test]
+fn contains_respects_endpoint_kinds() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), o(5));
+    assert!(s.contains(1.0));
+    assert!(s.contains(4.999));
+    assert!(!s.contains(5.0));
+    assert!(!s.contains(0.999));
+}
+
+#[test]
+fn measure_sums_lengths_without_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), c(5));
+    s.insert(c(7), c(7));
+    assert_eq!(s.measure(), 4);
+
+    let mut s = IntervalSet::new();
+    s.insert(c(i64::MIN), c(i64::MAX));
+    assert_eq!(s.measure(), i64::MAX as i128 - i64::MIN as i128);
+    assert!(s.contains(i64::MIN as f64));
+    assert!(s.contains(i64::MAX as f64));
+}
+
+#[test]
+fn complement_within_window() {
+    let mut s = IntervalSet::new();
+    s.insert(c(2), o(4));
+    s.insert(o(6), c(8));
+    assert_eq!(
+        s.complement(c(0), c(10)),
+        vec![(c(0), o(2)), (c(4), c(6)), (o(8), c(10))]
+    );
+}
+
+#[test]
+fn complement_empty_or_fully_covered_is_empty() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), c(5));
+    assert_eq!(s.complement(c(2), c(3)), Vec::new());
+    assert_eq!(s.complement(o(3), o(3)), Vec::new());
+}
+
+#[test]
+fn display_formats_canonical_form() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), o(3));
+    s.insert(o(4), c(5));
+    s.insert(c(7), c(7));
+    assert_eq!(format!("{}", s), "{[1,3), (4,5], [7,7]}");
+
+    let mut s = IntervalSet::new();
+    s.insert(o(-3), c(0));
+    assert_eq!(format!("{}", s), "{(-3,0]}");
+
+    let s = IntervalSet::new();
+    assert_eq!(format!("{}", s), "{}");
+}
+
+#[test]
+fn sweep_workload_runs_under_three_seconds() {
+    let mut rng: u64 = 0x9E37_79B9_7F4A_7C15;
+    let mut next = move || {
+        rng ^= rng << 13;
+        rng ^= rng >> 7;
+        rng ^= rng << 17;
+        rng
+    };
+
+    let mut s = IntervalSet::new();
+    let start = Instant::now();
+    let n: i64 = 300_000;
+    for i in 0..n {
+        let base = 1_000_000_000i64 - i * (1_000_000_000 / n);
+        let jitter = (next() % 4001) as i64 - 2000;
+        let lo = base + jitter;
+        let len = (next() % 1001) as i64;
+        let hi = lo + len;
+        if i % 2 == 0 {
+            s.insert(c(lo), o(hi));
+        } else {
+            s.remove(c(lo), c(hi));
+        }
+        let x = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(x);
+    }
+    let elapsed = start.elapsed();
+    assert!(
+        elapsed.as_secs_f64() < 3.0,
+        "workload took {:?}",
+        elapsed
+    );
+}

