+use statkit::report::summary;
+use statkit::stats::{count, mean, median, percentile};
+
+const NAN: f64 = f64::NAN;
+
+fn close(a: Option<f64>, expected: f64) -> bool {
+    match a {
+        Some(v) => (v - expected).abs() < 1e-9,
+        None => false,
+    }
+}
+
+#[test]
+fn count_ignores_nan_values() {
+    assert_eq!(count(&[1.0, NAN, 3.0]), 2);
+    assert_eq!(count(&[NAN, NAN]), 0);
+    assert_eq!(count(&[]), 0);
+    assert_ne!(count(&[1.0, NAN, 3.0]), 3);
+}
+
+#[test]
+fn mean_ignores_nan_and_is_none_when_empty() {
+    assert!(close(mean(&[1.0, 2.0, 3.0, 4.0]), 2.5));
+    assert!(close(mean(&[1.0, NAN, 3.0]), 2.0));
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[NAN, NAN]), None);
+    assert!(mean(&[NAN, 1.0]).map_or(false, |m| !m.is_nan()));
+}
+
+#[test]
+fn median_ignores_nan_and_is_none_when_empty() {
+    assert!(close(median(&[1.0, 2.0, 3.0, 4.0]), 2.5));
+    assert!(close(median(&[3.0, 1.0, 2.0]), 2.0));
+    assert!(close(median(&[NAN, 1.0, 3.0]), 2.0));
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[NAN]), None);
+    assert!(median(&[NAN, 5.0]).map_or(false, |m| !m.is_nan()));
+}
+
+#[test]
+fn percentile_uses_linear_interpolation_between_closest_ranks() {
+    let values = [1.0, 2.0, 3.0, 4.0];
+    assert!(close(percentile(&values, 0.0), 1.0));
+    assert!(close(percentile(&values, 100.0), 4.0));
+    assert!(close(percentile(&values, 50.0), 2.5));
+    assert!(close(percentile(&values, 90.0), 3.7));
+    assert!(!close(percentile(&values, 50.0), 2.0));
+}
+
+#[test]
+fn percentile_does_not_depend_on_input_order_and_leaves_input_unchanged() {
+    let shuffled = [4.0, 1.0, 3.0, 2.0];
+    assert!(close(percentile(&shuffled, 90.0), 3.7));
+    assert!(close(percentile(&shuffled, 50.0), 2.5));
+    assert_eq!(shuffled, [4.0, 1.0, 3.0, 2.0]);
+}
+
+#[test]
+fn percentile_ignores_nan_and_rejects_invalid_p_or_empty_input() {
+    assert!(close(percentile(&[NAN, 1.0, 2.0, 3.0, 4.0], 90.0), 3.7));
+    assert_eq!(percentile(&[], 50.0), None);
+    assert_eq!(percentile(&[NAN, NAN], 50.0), None);
+    assert_eq!(percentile(&[1.0, 2.0], NAN), None);
+    assert_eq!(percentile(&[1.0, 2.0], -1.0), None);
+    assert_eq!(percentile(&[1.0, 2.0], 101.0), None);
+    assert!(percentile(&[1.0, 2.0], 100.0).is_some());
+}
+
+#[test]
+fn summary_formats_report_with_two_decimals() {
