+    let order = Order::new("o")
+        .with_line("pear", 2)
+        .with_line("apple", 1)
+        .with_line("pear", 3)
+        .with_line("fig", 0);
+    assert_eq!(
+        order.quantities_by_sku(),
+        vec![("apple".to_string(), 1), ("pear".to_string(), 5)]
+    );
+}
+
+#[test]
+fn reserve_reduces_available_and_commit_keeps_it() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 4)).unwrap();
+    assert_eq!(inv.available("apple"), 6);
+    assert_eq!(inv.on_hand("apple"), 10);
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 6);
+    assert_eq!(inv.available("apple"), 6);
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn release_frees_units_without_changing_on_hand() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 3);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 3)).unwrap();
+    assert_eq!(inv.available("apple"), 0);
+    inv.release(id).unwrap();
+    assert_eq!(inv.available("apple"), 3);
+    assert_eq!(inv.on_hand("apple"), 3);
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn reserve_is_all_or_nothing_and_reports_first_failure() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let order = Order::new("o")
+        .with_line("apple", 2)
+        .with_line("ghost", 1)
+        .with_line("pear", 9);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::UnknownSku("ghost".to_string()))
+    );
+    assert_eq!(inv.available("apple"), 5);
+
+    inv.add_stock("pear", 1);
+    let order = Order::new("o2").with_line("apple", 2).with_line("pear", 9);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::Insufficient {
+            sku: "pear".to_string(),
+            requested: 9,
+            available: 1,
+        })
+    );
+    assert_eq!(inv.available("apple"), 5);
+    assert_eq!(inv.available("pear"), 1);
