+  expect(cartTotal(tiny, "FLAT5")).toBe(0 + 499);
+});
+
+test("FREESHIP waives shipping but not the subtotal", () => {
+  expect(cartTotal(small, "FREESHIP")).toBe(2400);
+});
+
+test("free shipping eligibility uses the pre-discount subtotal", () => {
+  // 5000 pre-discount qualifies for free shipping even though SAVE10 drops it to 4500
+  const threshold = [{ sku: "desk", priceCents: 5000, qty: 1 }];
+  expect(cartTotal(threshold, "SAVE10")).toBe(4500);
+});
+
+test("unknown code throws InvalidDiscountError", () => {
