diff --git a/test/cron.test.ts b/test/cron.test.ts
new file mode 100644
index 0000000..5622645
--- /dev/null
+++ b/test/cron.test.ts
@@ -0,0 +1,168 @@
+import { expect, test } from "bun:test";
+import { CronError, nextRun } from "../src/cron";
+
+const utc = (s: string) => new Date(s);
+
+test("every 15 minutes from a mid-minute start", () => {
+  expect(nextRun("*/15 * * * *", utc("2024-01-01T10:07:33.500Z")).toISOString()).toBe(
+    "2024-01-01T10:15:00.000Z",
+  );
+});
+
+test("does not modify from", () => {
+  const from = utc("2024-01-01T10:07:33.500Z");
+  nextRun("* * * * *", from);
+  expect(from.toISOString()).toBe("2024-01-01T10:07:33.500Z");
+});
+
+test("minute ranges with steps", () => {
+  expect(nextRun("10-50/20 * * * *", utc("2024-01-01T00:11:00Z")).toISOString()).toBe(
+    "2024-01-01T00:30:00.000Z",
+  );
+});
+
+test("names are case-insensitive in month and day-of-week", () => {
+  // Jan 1 2024 is a Monday; the next 09:00 on a weekday after 10:00 Monday is Tuesday Jan 2.
+  expect(nextRun("0 9 * jan,Jul MON-FRI", utc("2024-01-01T10:00:00Z")).toISOString()).toBe(
+    "2024-01-02T09:00:00.000Z",
+  );
+});
+
+test("day-of-week 7 means Sunday", () => {
+  expect(nextRun("0 0 * * 7", utc("2024-01-01T00:00:00Z")).toISOString()).toBe(
+    "2024-01-07T00:00:00.000Z",
+  );
+});
+
+test("classic OR rule when both day fields are restricted", () => {
+  // Monday or the 15th: from Jan 2 the next match is Jan 8 (Monday).
+  expect(nextRun("0 0 15 * 1", utc("2024-01-02T00:00:00Z")).toISOString()).toBe(
+    "2024-01-08T00:00:00.000Z",
+  );
+});
+
+test("0 0 L * 1 runs on last day of month or Monday", () => {
+  expect(nextRun("0 0 L * 1", utc("2024-02-27T00:00:00Z")).toISOString()).toBe(
+    "2024-02-29T00:00:00.000Z",
+  );
+});
+
+test("0 0 * 2 5L runs only on the last Friday of February", () => {
+  // Last Friday of Feb 2024 is Feb 23.
+  expect(nextRun("0 0 * 2 5L", utc("2024-01-01T00:00:00Z")).toISOString()).toBe(
+    "2024-02-23T00:00:00.000Z",
+  );
+});
+
+test("nth weekday: 5#3 is the third Friday", () => {
+  // Third Friday of Jan 2024 is Jan 19.
+  expect(nextRun("0 0 * 1 FRI#3", utc("2024-01-01T00:00:00Z")).toISOString()).toBe(
+    "2024-01-19T00:00:00.000Z",
+  );
+});
+
+test("5#5 skips months without a fifth Friday", () => {
+  // Fifth Friday of 2024: Mar 29 is the 5th Friday (Mar 1,8,15,22,29).
+  expect(nextRun("0 0 * * 5#5", utc("2024-01-01T00:00:00Z")).toISOString()).toBe(
+    "2024-03-29T00:00:00.000Z",
+  );
+});
+
+test("L is the last day of month", () => {
+  expect(nextRun("0 0 L 2 *", utc("2023-01-01T00:00:00Z")).toISOString()).toBe(
+    "2023-02-28T00:00:00.000Z",
+  );
+});
+
+test("LW is the last weekday of month", () => {
+  // Aug 31 2024 is a Saturday, so LW is Aug 30.
+  expect(nextRun("0 0 LW 8 *", utc("2024-01-01T00:00:00Z")).toISOString()).toBe(
+    "2024-08-30T00:00:00.000Z",
+  );
+});
+
+test("nW: Saturday resolves to Friday, except day 1 resolves to Monday 3rd", () => {
+  // June 15 2024 is a Saturday -> Friday June 14.
+  expect(nextRun("0 0 15W 6 *", utc("2024-01-01T00:00:00Z")).toISOString()).toBe(
+    "2024-06-14T00:00:00.000Z",
+  );
+  // June 1 2024 is a Saturday -> Monday June 3.
+  expect(nextRun("0 0 1W 6 *", utc("2024-01-01T00:00:00Z")).toISOString()).toBe(
+    "2024-06-03T00:00:00.000Z",
+  );
+});
+
+test("nW: Sunday resolves to Monday, except last day resolves to Friday", () => {
+  // June 16 2024 is a Sunday -> Monday June 17.
+  expect(nextRun("0 0 16W 6 *", utc("2024-01-01T00:00:00Z")).toISOString()).toBe(
+    "2024-06-17T00:00:00.000Z",
+  );
+  // Nov 30 2025 is a Sunday and the last day of November -> Friday Nov 28.
+  expect(nextRun("0 0 30W 11 *", utc("2025-01-01T00:00:00Z")).toISOString()).toBe(
+    "2025-11-28T00:00:00.000Z",
+  );
+});
+
+test("31W never matches in February", () => {
+  expect(() => nextRun("0 0 31W 2 *", utc("2024-01-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("@ aliases", () => {
+  expect(nextRun("@HOURLY", utc("2024-01-01T10:30:00Z")).toISOString()).toBe(
+    "2024-01-01T11:00:00.000Z",
+  );
+  expect(nextRun("@monthly", utc("2024-01-02T00:00:00Z")).toISOString()).toBe(
+    "2024-02-01T00:00:00.000Z",
+  );
+});
+
+test("invalid expressions throw CronError", () => {
+  const bad = [
+    "* * * *",
+    "60 * * * *",
+    "*/0 * * * *",
+    "5/15 * * * *",
+    "5-1 * * * *",
+    "1,,2 * * * *",
+    "JAN * * * *",
+    "* * * * FOO",
+    "@sometimes",
+    "@daily 5",
+    "L * * * *",
+    "1-5W * * *",
+    "* * * * L",
+    "* * * * W",
+    "* * * * 5W",
+    "* * * * 5L/2",
+    "* * * * 8#1",
+    "* * * * 5#0",
+    "* * * * 5#6",
+    "* * * * 5#",
+    "* * 0 * *",
+    "* * 32 * *",
+    "* * L/2 * *",
+    "0 0 30 2 *",
+  ];
+  for (const expr of bad) {
+    expect(() => nextRun(expr, utc("2024-01-01T00:00:00Z"))).toThrow(CronError);
+  }
+});
+
+test("performance: 3000 calls across schedules finish under 2 seconds", () => {
+  const schedules = ["0 0 29 2 1", "59 23 31 12 5L", "0 0 LW 2 *", "30 4 15W * 1#5", "0 0 29 2 *"];
+  const started = performance.now();
+  let i = 0;
+  for (let call = 0; call < 3000; call++) {
+    const year = 2000 + (call % 100);
+    const from = new Date(Date.UTC(year, call % 12, 1 + (call % 28), 12, 0, 0));
+    try {
+      nextRun(schedules[call % schedules.length], from);
+    } catch (e) {
+      if (!(e instanceof CronError)) throw e;
+    }
+    i++;
+  }
+  const elapsed = performance.now() - started;
+  expect(i).toBe(3000);
+  expect(elapsed).toBeLessThan(2000);
+});

