+package config
+
+import (
+	"testing"
+	"time"
+)
+
+func TestParseFileSplitsOnFirstEquals(t *testing.T) {
+	got, err := ParseFile("a = b=c")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if got["a"] != "b=c" {
+		t.Fatalf("a = %q, want %q", got["a"], "b=c")
+	}
+}
+
+func TestFromEnvIgnoresEmptyValues(t *testing.T) {
+	got := FromEnv(map[string]string{"APP_PORT": "", "APP_LOG_LEVEL": "debug"})
+	if len(got) != 1 || got["log_level"] != "debug" {
+		t.Fatalf("FromEnv = %v, want {log_level: debug}", got)
+	}
+}
+
+func TestDurationForms(t *testing.T) {
+	cases := map[string]time.Duration{
+		"90":    90 * time.Second,
+		"1m30s": 90 * time.Second,
+		"250ms": 250 * time.Millisecond,
+		"1.5s":  1500 * time.Millisecond,
+		"2h":    2 * time.Hour,
+		"bogus": 7 * time.Second,
+	}
+	for in, want := range cases {
+		c := Merge(map[string]string{"timeout": in})
+		if got := c.Duration("timeout", 7*time.Second); got != want {
+			t.Errorf("Duration(%q) = %v, want %v", in, got, want)
+		}
+	}
+}

