+use exprkit::{eval, EvalError};
+use std::collections::HashMap;
+
+fn run(s: &str) -> Result<f64, EvalError> {
+    eval(s, &HashMap::new())
+}
+
+fn with_x(s: &str) -> Result<f64, EvalError> {
+    let mut vars = HashMap::new();
+    vars.insert("x".to_string(), 5.0);
+    vars.insert("y".to_string(), 3.0);
+    eval(s, &vars)
+}
+
+fn perr(pos: usize) -> Result<f64, EvalError> {
+    Err(EvalError::Parse { pos })
+}
+
+#[test]
+fn precedence_and_associativity() {
+    assert_eq!(run("-2^2"), Ok(-4.0));
+    assert_eq!(run("(-2)^2"), Ok(4.0));
+    assert_eq!(run("2^-1"), Ok(0.5));
+    assert_eq!(run("2^3^2"), Ok(512.0));
+    assert_eq!(run("--3"), Ok(3.0));
+    assert_eq!(run("2--2"), Ok(4.0));
+    assert_eq!(run("7 % 4 % 2"), Ok(1.0));
+    assert_eq!(run("-7 % 3"), Ok(-1.0));
+    assert_eq!(run("7.5 % 2"), Ok(1.5));
+}
+
+#[test]
+fn implicit_multiplication() {
+    assert_eq!(with_x("2x"), Ok(10.0));
+    assert_eq!(with_x("2 x"), Ok(10.0));
+    assert_eq!(with_x("x y"), Ok(15.0));
+    assert_eq!(run("2(3+4)"), Ok(14.0));
+    assert_eq!(run("(1+2)(3+4)"), Ok(21.0));
+    assert_eq!(run("2(3)(4)"), Ok(24.0));
+    assert_eq!(run("3abs(-2)"), Ok(6.0));
+    assert_eq!(with_x("2x^2"), Ok(50.0));
+    assert_eq!(with_x("-2x"), Ok(-10.0));
+    assert!(run("2^3x").is_err());
+    assert_eq!(run("6/2(1+2)"), Ok(9.0));
+}
+
+#[test]
+fn functions_and_errors() {
+    assert_eq!(run("min(3, 1, 2)"), Ok(1.0));
+    assert_eq!(run("max(3, 1, 2)"), Ok(3.0));
+    assert_eq!(run("sqrt(16)"), Ok(4.0));
+    assert_eq!(run("sqrt(-1)"), Err(EvalError::Domain("sqrt".to_string())));
+    assert_eq!(run("1/0"), Err(EvalError::DivByZero));
+    assert_eq!(run("1%(-0.0)"), Err(EvalError::DivByZero));
+    assert_eq!(run("min()"), Err(EvalError::Arity { name: "min".into(), expected: "at least 1".into(), got: 0 }));
+    assert_eq!(run("abs(1, 2)"), Err(EvalError::Arity { name: "abs".into(), expected: "1".into(), got: 2 }));
+    assert_eq!(with_x("x(1)"), Err(EvalError::UnknownFunc("x".into())));
+    assert_eq!(run("q"), Err(EvalError::UnknownVar("q".into())));
+}
+
+#[test]
+fn parse_error_positions() {
+    assert_eq!(run("2 3"), perr(2));
+    assert_eq!(run("(2)3"), perr(3));
+    assert!(run("x 2").is_err());
+    assert_eq!(run("1 + 2)"), perr(5));
+    assert_eq!(run("()"), perr(1));
+    assert_eq!(run("X"), perr(0));
+    assert_eq!(run("1,2"), perr(1));
+    assert_eq!(run("min(1 2)"), perr(6));
+    assert_eq!(run("min(,1)"), perr(4));
+    assert_eq!(run("min(1,)"), perr(6));
+    assert_eq!(run(""), perr(0));
+    assert_eq!(run("   "), perr(3));
+    assert_eq!(run("(1 + 2"), perr(6));
+    assert_eq!(run("1 +"), perr(3));
+    assert_eq!(run("max(1"), perr(5));
+    assert_eq!(run(".5"), perr(0));
+    assert_eq!(run("5."), perr(1));
+}
+
+#[test]
+fn parse_errors_win_over_eval_errors() {
+    assert_eq!(run("1/0 + )"), perr(6));
+}
+
+#[test]
+fn deep_inputs() {
+    let n = 100000;
+    let s = format!("{}1{}", "(".repeat(n), ")".repeat(n));
+    assert_eq!(run(&s), Ok(1.0));
+
+    let s = format!("{}-3{}", "abs(".repeat(n), ")".repeat(n));
+    assert_eq!(run(&s), Ok(3.0));
+
+    let s = format!("{}5{}", "max(1, ".repeat(n), ")".repeat(n));
+    assert_eq!(run(&s), Ok(5.0));
+
+    let s = format!("{}1", "-".repeat(n));
+    assert_eq!(run(&s), Ok(1.0));
+
+    let s = format!("{}1", "1^".repeat(n));
+    assert_eq!(run(&s), Ok(1.0));
+
+    let s = vec!["1"; 200000].join("+");
+    assert_eq!(run(&s), Ok(200000.0));
+
+    let s = "(1)".repeat(n);
+    assert_eq!(run(&s), Ok(1.0));
+}

s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Closed(5));
+    s.remove(Bound::Open(2), Bound::Open(2));
+    s.remove(Bound::Closed(4), Bound::Closed(2));
+    assert_eq!(s.ranges(), vec![(Bound::Closed(1), Bound::Closed(5))]);
+}
+
+#[test]
+fn ranges_merge_when_union_is_single_interval() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Open(3));
+    s.insert(Bound::Closed(3), Bound::Closed(5));
+    assert_eq!(s.ranges(), vec![(Bound::Closed(1), Bound::Closed(5))]);
+
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Closed(3));
+    s.insert(Bound::Open(3), Bound::Open(5));
+    assert_eq!(s.ranges(), vec![(Bound::Closed(1), Bound::Open(5))]);
+
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Open(1), Bound::Open(3));
+    s.insert(Bound::Closed(3), Bound::Closed(3));
+    assert_eq!(s.ranges(), vec![(Bound::Open(1), Bound::Closed(3))]);
+
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Closed(4));
+    s.insert(Bound::Closed(2), Bound::Open(6));
+    assert_eq!(s.ranges(), vec![(Bound::Closed(1), Bound::Open(6))]);
+}
+
+#[test]
+fn ranges_keep_gaps_separate() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Open(1), Bound::Open(3));
+    s.insert(Bound::Open(3), Bound::Open(5));
+    assert_eq!(
+        s.ranges(),
+        vec![
+            (Bound::Open(1), Bound::Open(3)),
+            (Bound::Open(3), Bound::Open(5)),
+        ]
+    );
+
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Open(3));
+    s.insert(Bound::Open(3), Bound::Closed(5));
+    assert_eq!(
+        s.ranges(),
+        vec![
+            (Bound::Closed(1), Bound::Open(3)),
+            (Bound::Open(3), Bound::Closed(5)),
+        ]
+    );
+}
+
+#[test]
+fn single_point_is_closed_pair() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Open(7), Bound::Closed(7));
+    s.insert(Bound::Closed(7), Bound::Closed(7));
+    assert_eq!(s.ranges(), vec![(Bound::Closed(7), Bound::Closed(7))]);
+    assert_eq!(s.measure(), 0);
+}
+
+#[test]
+fn measure_sums_lengths() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Open(5));
+    s.insert(Bound::Open(10), Bound::Closed(20));
+    s.insert(Bound::Closed(30), Bound::Closed(30));
+    assert_eq!(s.measure(), 14);
+    assert_ne!(s.measure(), 15);
+    assert_eq!(IntervalSet::new().measure(), 0);
+}
+
+#[test]
+fn measure_full_i64_range_does_not_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX));
+    assert_eq!(s.measure(), u64::MAX as i128);
+    assert_ne!(s.measure(), 0);
+}
+
+#[test]
+fn display_formats_canonical_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(7), Bound::Closed(7));
+    s.insert(Bound::Open(4), Bound::Closed(5));
+    s.insert(Bound::Closed(1), Bound::Open(3));
+    assert_eq!(format!("{}", s), "{[1,3), (4,5], [7,7]}");
+
+    let mut t = IntervalSet::new();
+    t.insert(Bound::Open(-3), Bound::Closed(0));
+    assert_eq!(format!("{}", t), "{(-3,0]}");
+    assert_ne!(format!("{}", t), "{[-3,0]}");
+    assert_eq!(format!("{}", IntervalSet::new()), "{}");
+}
+
+#[test]
+fn complement_flips_endpoints_at_window_edges() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(2), Bound::Open(4));
+    s.insert(Bound::Open(6), Bound::Closed(8));
+    assert_eq!(
+        s.complement(Bound::Closed(0), Bound::Closed(10)),
+        vec![
+            (Bound::Closed(0), Bound::Open(2)),
+            (Bound::Closed(4), Bound::Closed(6)),
+            (Bound::Open(8), Bound::Closed(10)),
+        ]
+    );
+    assert_ne!(
+        s.complement(Bound::Closed(0), Bound::Closed(10)),
+        vec![(Bound::Closed(0), Bound::Closed(10))]
+    );
+}
+
+#[test]
+fn complement_empty_window_and_full_cover() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(0), Bound::Closed(10));
+    assert_eq!(s.complement(Bound::Closed(2), Bound::Closed(5)), vec![]);
+    assert_eq!(s.complement(Bound::Open(3), Bound::Open(3)), vec![]);
+
+    let empty = IntervalSet::new();
+    assert_eq!(
+        empty.complement(Bound::Closed(2), Bound::Open(5)),
+        vec![(Bound::Closed(2), Bound::Open(5))]
+    );
+    assert_ne!(empty.complement(Bound::Closed(2), Bound::Open(5)), vec![]);
+}
+
+#[test]
+fn full_range_extremes_work() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX));
+    assert!(s.contains(i64::MIN as f64));
+    assert!(s.contains(i64::MAX as f64));
+    assert!(!s.contains(1e19));
+
+    s.remove(Bound::Open(i64::MIN), Bound::Open(i64::MAX));
+    assert_eq!(
+        s.ranges(),
+        vec![
+            (Bound::Closed(i64::MIN), Bound::Closed(i64::MIN)),
+            (Bound::Closed(i64::MAX), Bound::Closed(i64::MAX)),
+        ]
+    );
+    assert!(!s.contains(0.0));
+}
+
+#[test]
+fn large_sweep_workload_is_fast() {
+    let mut state: u64 = 0x2545_F491_4F6C_DD1D;
+    let mut next = move || {
+        state = state
+            .wrapping_mul(6364136223846793005)
+            .wrapping_add(1442695040888963407);
+        state >> 33
+    };
+    let start = Instant::now();
+    let mut s = IntervalSet::new();
+    let mut hits = 0u64;
+    for i in 0..300_000i64 {
+        let base = 1_000_000_000i64 - i * 3333;
+        let jitter = (next() % 2001) as i64 - 1000;
+        let lo = base + jitter;
+        let len = (next() % 1001) as i64;
+        s.insert(Bound::Closed(lo), Bound::Closed(lo + len));
+        let rlo = lo - (next() % 5000) as i64;
+        s.remove(Bound::Closed(rlo), Bound::Closed(rlo + len));
+        let probe = (next() % 1_000_000_001) as f64;
+        if s.contains(probe) {
+            hits += 1;
+        }
+    }
+    let elapsed = start.elapsed();
+    assert!(elapsed.as_secs_f64() < 3.0, "took {:?}", elapsed);
+    assert!(hits <= 300_000);
+    assert!(s.measure() >= 0);
+}

