+use romankit::{from_roman, to_roman, RomanError};
+
+#[test]
+fn to_roman_rejects_values_outside_1_to_3999() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(u32::MAX), Err(RomanError::OutOfRange)));
+}
+
+#[test]
+fn to_roman_renders_range_bounds() {
+    assert_eq!(to_roman(1).ok().as_deref(), Some("I"));
+    assert_eq!(to_roman(3999).ok().as_deref(), Some("MMMCMXCIX"));
+    assert_ne!(to_roman(4000).ok().as_deref(), Some("MMMM"));
+}
+
+#[test]
+fn from_roman_reads_subtractive_endings() {
+    assert_eq!(from_roman("IV").ok(), Some(4));
+    assert_eq!(from_roman("XIX").ok(), Some(19));
+    assert_eq!(from_roman("MCMXCIX").ok(), Some(1999));
+    assert_ne!(from_roman("XIX").ok(), Some(21));
+}
+
+#[test]
+fn from_roman_rejects_non_canonical_forms() {
+    for s in ["IIII", "IC", "VX", "MMMM", "IIV", "XM"].iter() {
+        assert!(matches!(from_roman(s), Err(RomanError::NonCanonical)), "{}", s);
+    }
+}
+
+#[test]
+fn from_roman_rejects_empty_string() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+}
+
+#[test]
+fn from_roman_reports_first_invalid_character() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("I V"), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("IVzQ"), Err(RomanError::InvalidChar('z'))));
+    assert!(matches!(from_roman("IIIIz"), Err(RomanError::InvalidChar('z'))));
+}
+
+#[test]
+fn from_roman_never_reports_out_of_range() {
+    for s in ["MMMM", "MMMMM", "MMMMCMXCIX"].iter() {
+        assert!(!matches!(from_roman(s), Err(RomanError::OutOfRange)), "{}", s);
+    }
+}
+
+#[test]
+fn round_trip_holds_for_every_valid_number() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).expect("1..=3999 must render");
+        assert_eq!(from_roman(&s).ok(), Some(n), "{}", s);
+    }
+}
+
+#[test]
+fn from_roman_accepts_exactly_the_canonical_forms() {
+    let letters = ['I', 'V', 'X', 'L', 'C', 'D', 'M'];
+    for len in 1..=5u32 {
+        for k in 0..7usize.pow(len) {
+            let mut x = k;
+            let mut s = String::new();
+            for _ in 0..len {
+                s.push(letters[x % 7]);
+                x /= 7;
+            }
+            match from_roman(&s) {
+                Ok(n) => assert_eq!(to_roman(n).ok().as_deref(), Some(s.as_str()), "{}", s),
+                Err(e) => assert!(matches!(e, RomanError::NonCanonical), "{}", s),
+            }
+        }
+    }
+}
