+use statkit::report::summary;
+use statkit::stats::{count, mean, median, percentile};
+
+fn near(actual: Option<f64>, expected: f64) -> bool {
+    match actual {
+        Some(v) => (v - expected).abs() < 1e-9,
+        None => false,
+    }
+}
+
+#[test]
+fn summary_matches_expected_line_for_sorted_input() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_is_independent_of_input_order() {
+    assert_eq!(summary(&[3.0, 1.0, 4.0, 2.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[4.0, 3.0, 2.0, 1.0]), summary(&[1.0, 2.0, 3.0, 4.0]));
+}
+
+#[test]
+fn summary_of_empty_input_is_just_count() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_ne!(summary(&[]), "n=0 mean=NaN p50=0.00 p90=0.00");
+}
+
+#[test]
+fn summary_ignores_nan_values() {
+    assert_eq!(summary(&[1.0, f64::NAN, 3.0]), "n=2 mean=2.00 p50=2.00 p90=2.80");
+    assert_eq!(summary(&[f64::NAN, f64::NAN]), "n=0");
+    assert!(!summary(&[1.0, f64::NAN, 3.0]).contains("NaN"));
+}
+
+#[test]
+fn summary_single_value_formats_all_stats_as_that_value() {
+    assert_eq!(summary(&[5.0]), "n=1 mean=5.00 p50=5.00 p90=5.00");
+}
+
+#[test]
+fn count_returns_number_of_non_nan_values() {
+    assert_eq!(count(&[1.0, 2.0, 3.0]), 3);
+    assert_eq!(count(&[1.0, f64::NAN, 3.0]), 2);
+    assert_ne!(count(&[1.0, f64::NAN, 3.0]), 3);
+    assert_eq!(count(&[f64::NAN]), 0);
+    assert_eq!(count(&[]), 0);
+}
+
+#[test]
+fn mean_ignores_nan_and_is_none_without_values() {
+    assert!(near(mean(&[1.0, 2.0, 3.0, 4.0]), 2.5));
+    assert!(near(mean(&[1.0, f64::NAN, 3.0]), 2.0));
+    assert!(!mean(&[1.0, f64::NAN, 3.0]).unwrap().is_nan());
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[f64::NAN, f64::NAN]), None);
+}
+
+#[test]
+fn median_is_percentile_fifty_and_ignores_nan() {
+    assert!(near(median(&[1.0, 2.0, 3.0, 4.0]), 2.5));
+    assert!(near(median(&[3.0, 1.0, 2.0]), 2.0));
+    assert!(near(median(&[1.0, f64::NAN, 3.0]), 2.0));
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[f64::NAN]), None);
+}
+
+#[test]
+fn percentile_uses_linear_interpolation_between_closest_ranks() {
+    assert!(near(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0), 3.7));
+    assert!(near(percentile(&[1.0, 2.0, 3.0, 4.0], 50.0), 2.5));
+    assert!(!near(percentile(&[1.0, 2.0, 3.0, 4.0], 50.0), 2.0));
+}
+
+#[test]
+fn percentile_endpoints_are_min_and_max() {
+    assert!(near(percentile(&[4.0, 1.0, 3.0, 2.0], 0.0), 1.0));
+    assert!(near(percentile(&[4.0, 1.0, 3.0, 2.0], 100.0), 4.0));
+    assert!(!near(percentile(&[4.0, 1.0, 3.0, 2.0], 100.0), 3.0));
+}
+
+#[test]
+fn percentile_does_not_depend_on_input_order() {
+    assert!(near(percentile(&[4.0, 1.0, 3.0, 2.0], 90.0), 3.7));
+    assert!(near(percentile(&[2.0, 4.0, 1.0, 3.0], 90.0), 3.7));
+}
+
+#[test]
+fn percentile_ignores_nan_values() {
+    assert!(near(percentile(&[1.0, f64::NAN, 3.0], 90.0), 2.8));
+    assert_eq!(percentile(&[f64::NAN, f64::NAN], 50.0), None);
